const src = $json.body ?? $json;
const owner = src.repository_owner ?? "";
const repo = src.repository_name ?? "";
const number = Number(src.issue_number ?? 0);
const item = {
  delivery_id: src.delivery_id ?? ("reconcile:" + owner + "/" + repo + "#" + number),
  repository_owner: owner,
  repository_name: repo,
  issue_number: number,
  title: src.title ?? "",
  body: src.body ?? "",
  labels: src.labels ?? [],
  author: src.author ?? "",
  issue_url: src.issue_url ?? ""
};
return { json: { item, payload: JSON.stringify(item) } };
